def die(m):
    print("\nABORT:", m); sys.exit(1)


def mirror_of(rel):
    return os.path.join(ROOT, MIRROR + rel[len("frontend/src"):])


print(f"── {FENCE} ── root {ROOT}")
staged = {}
for rel, parent in PREREQ.items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p):
        die(f"{rel} not found — run from the repo root")
    t = open(p, encoding="utf-8").read()
    if FENCE in t:
        die(f"{FENCE} already applied ({rel})")
    if parent not in t:
        die(f"prerequisite {parent} missing in {rel} — fetch/apply the dashboard chain first")
pre = hashlib.sha256(open(os.path.join(ROOT, CHART), "rb").read()).hexdigest()
if pre != CHART_PRE_SHA:
    die(f"{CHART} differs from the version this script was built on (FLEET_CHART_V2 as on GitHub main, 2026-10-07); "
        "it was edited since — send it to me rather than overwrite it")
staged[CHART] = base64.b64decode(CHART_B64).decode("utf-8")
for rel, ops in EDITS.items():
    t = open(os.path.join(ROOT, rel), encoding="utf-8").read()
    for kind, old, new in ops:
        n = t.count(old)
        if n != 1:
            die(f"{rel}: anchor found {n}x (need 1): {old.splitlines()[0][:80]!r}")
        t = t.replace(old, new)
    staged[rel] = t
st = subprocess.run(["git", "status", "--porcelain", "--"] + list(staged), cwd=ROOT, capture_output=True, text=True).stdout
dirty = [l for l in st.splitlines() if l.strip() and not l.startswith("??")]
if dirty and "--allow-dirty" not in sys.argv:
    die(f"uncommitted changes on targets ({dirty}); commit or re-run with --allow-dirty")
print(f"   prerequisites ok, FleetChart pre-image ok, {len(staged)} files staged")

written = []
for rel, txt in staged.items():
    p = os.path.join(ROOT, rel)
    shutil.copy2(p, p + f".bak-{FENCE}")
    open(p, "w", encoding="utf-8").write(txt)
    written.append(rel)
    m = mirror_of(rel)
    if os.path.isdir(os.path.dirname(m)):
        open(m, "w", encoding="utf-8").write(txt)
open(os.path.join(ROOT, f".{FENCE}.done"), "w").write("applied\n")
print(f"   wrote {len(written)} files (backups .bak-{FENCE}; desktop tree mirrored where present)")


def rollback(reason):
    for rel in written:
        p = os.path.join(ROOT, rel)
        shutil.move(p + f".bak-{FENCE}", p)
        m = mirror_of(rel)
        if os.path.exists(m):
            shutil.copy2(p, m)
    os.remove(os.path.join(ROOT, f".{FENCE}.done"))
    die(reason)


esb = os.path.join(ROOT, "frontend", "node_modules", ".bin", "esbuild")
esb = os.environ.get("ESBUILD") or (esb if os.path.exists(esb) else shutil.which("esbuild"))
if esb:
    for rel in written:
        r = subprocess.run([esb, rel, "--loader:.jsx=jsx", "--log-level=error", "--outfile=/dev/null"], cwd=ROOT, capture_output=True, text=True)
        if r.returncode != 0:
            rollback(f"esbuild parse failed for {rel}; restored:\n" + r.stderr[-1500:])
        print(f"   esbuild ok {rel}")
else:
    print("   (esbuild not found — skipping parse gate; build-scalp.sh will compile)")
print(f"── {FENCE} applied. Next: ./desktop/build-scalp.sh frontend, relaunch (before 09:00 / after 15:40 IST), reload on the phone ──")
